409	///|
410	async fn try_flush_diagnostic_recording() -> Unit {
411	  if diagnostic_write_active.val ||
412	    (diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0) {
413	    return
414	  }
415	  diagnostic_write_active.val = true
416	  defer {
417	    diagnostic_write_active.val = false
418	  }
419	  let mut failure_phase = "directory"
420	  @async.with_timeout(50, async fn() {
421	    let dir = adapter_state_home()
422	    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
423	    @fs.chmod(dir, 0o700)
424	    let path = dir + "/events.jsonl"
425	    let lock_path = dir + "/events.lock"
426	    failure_phase = "lock"
427	    if @fs.exists(lock_path) &&
428	      @fs.kind(lock_path, follow_symlink=false) != @fs.FileKind::Regular {
429	      diagnostic_recording_warning("invalid_lock", phase=failure_phase)
430	      return
431	    }
432	    let lock = @fs.open(
433	      lock_path,
434	      mode=ReadWrite,
435	      create_mode=OpenOrCreate,
436	      permission=0o600,
437	    )
438	    defer lock.close()
439	    if !lock.try_lock(Exclusive) {
440	      diagnostic_recording_warning("lock_busy", phase=failure_phase)
441	      return
442	    }
443	    failure_phase = "inspect"
444	    if @fs.exists(path) &&
445	      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
446	      diagnostic_recording_warning("invalid_store", phase=failure_phase)
447	      return
448	    }
449	    let mut prefix = ""
450	    let mut replace = false
451	    if @fs.exists(path) {
452	      let file = @fs.open(path, mode=ReadOnly)
453	      defer file.close()
454	      let size = file.size()
455	      if size > 262144L {
456	        let marker = diagnostic_recording_event("rotated", "retention_limit")
457	        set_field(
458	          marker,
459	          "missingThroughTime",
460	          Json::string(@env.now().to_string()),
461	        )
462	        set_field(marker, "missingRange", Json::string("unknown"))
463	        prefix = marker.stringify() +
464	          "\n" +
465	          diagnostic_retained_records(file, size)
466	        replace = true
467	      } else if size > 0L {
468	        let tail = FixedArray::make(1, b'\x00')
469	        guard file.read_at(tail, position=size - 1L) == 1 else {
470	          raise AdapterError("Unable to inspect diagnostic record boundary")
471	        }
472	        if tail[0] != b'\n' {
473	          let bytes = FixedArray::make(size.to_int(), b'\x00')
474	          let read = file.read_at(bytes, position=0L)
475	          let mut complete = read
476	          while complete > 0 && bytes[complete - 1] != b'\n' {
477	            complete -= 1
478	          }
479	          prefix = @utf8.decode_lossy(
480	            bytes.unsafe_reinterpret_as_bytes()[:complete],
481	          )
482	          let marker = diagnostic_recording_event(
483	            "degraded",
484	            if read != size.to_int() {
485	              "short_read"
486	            } else {
487	              "incomplete_record"
488	            },
489	          )
490	          set_field(marker, "missingRange", Json::string("unknown"))
491	          prefix += marker.stringify() + "\n"
492	          replace = true
493	        }
494	      }
495	    }
496	    let recorded_drops = diagnostic_recording_health.dropped
497	    let incident_serial = diagnostic_recording_health.incident_serial
498	    if recorded_drops > 0 || diagnostic_recording_health.incident {
499	      let marker = diagnostic_recording_event(
500	        if recorded_drops > 0 {
501	          "degraded"
502	        } else {
503	          "recovered"
504	        },
505	        diagnostic_recording_health.reason,
506	      )
507	      if recorded_drops > 0 {
508	        set_field(
509	          marker,
510	          "droppedEvents",
511	          Json::number(recorded_drops.to_double()),
512	        )
513	        set_field(
514	          marker,
515	          "missingFromTime",
516	          Json::string(diagnostic_recording_health.first_dropped.to_string()),
517	        )
518	        set_field(
519	          marker,
520	          "missingThroughTime",
521	          Json::string(diagnostic_recording_health.last_dropped.to_string()),
522	        )
523	      } else {
524	        set_field(marker, "completeness", Json::string("complete"))
525	      }
526	      if diagnostic_recording_health.phase != "" {
527	        set_field(
528	          marker,
529	          "phase",
530	          Json::string(diagnostic_recording_health.phase),
531	        )
532	      }
533	      if diagnostic_recording_health.os_errno is Some(code) {
534	        set_field(marker, "osErrno", Json::number(code.to_double()))
535	      }
536	      prefix += marker.stringify() + "\n"
537	    }
538	    let count = diagnostic_pending.length()
539	    diagnostic_pending_inflight.val = count
540	    defer {
541	      diagnostic_pending_inflight.val = 0
542	    }
543	    let records = @buffer.Buffer(size_hint=4096)
544	    for index in 0..<count {
545	      records.write_string_utf8(
546	        diagnostic_pending[index].event.stringify() + "\n",
547	      )
548	    }
549	    let content = prefix + @utf8.decode_lossy(records.to_bytes())
550	    failure_phase = if replace { "replace" } else { "append" }
551	    if replace {
552	      let temporary = path + ".rotate." + proxy_pid().to_string()
553	      defer (@fs.remove(temporary) catch { _ => () })
554	      @fs.write_file(temporary, content, permission=0o600)
555	      @fs.rename(temporary, path, replace=true)
556	    } else {
557	      @fs.write_file(
558	        path,
559	        content,
560	        permission=0o600,
561	        append=true,
562	        create_mode=OpenOrCreate,
563	      )
564	    }
565	    for _ in 0..<count {
566	      ignore(diagnostic_pending.remove(0))
567	    }
568	    diagnostic_recording_health.dropped -= recorded_drops
569	    if diagnostic_recording_health.incident_serial == incident_serial {
570	      diagnostic_recording_health.incident = false
571	    }
572	  }) catch {
573	    error =>
574	      if !@async.is_being_cancelled() {
575	        diagnostic_recording_warning(
576	          if error is @async.TimeoutError {
577	            "store_timeout"
578	          } else {
579	            "store_unavailable"
580	          },
581	          phase=failure_phase,
582	          os_errno?=match error {
583	            @os_error.OSError(code, ..) => Some(code)
584	            _ => None
585	          },
586	        )
587	      }
588	  }
589	}
