592	async fn flush_diagnostic_recording() -> Unit {
593	  if diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0 {
594	    return
595	  }
596	  @async.with_timeout(1000, async fn() {
597	    while !diagnostic_pending.is_empty() ||
598	          diagnostic_recording_health.dropped > 0 {
599	      try_flush_diagnostic_recording()
600	      if !diagnostic_pending.is_empty() ||
601	        diagnostic_recording_health.dropped > 0 {
602	        @async.sleep(25)
603	      }
604	    }
605	  }) catch {
606	    error => if @async.is_being_cancelled() { raise error }
607	  }
608	}
