 616	fn diagnostic_error(
 617	  error : Error,
 618	  environment? : Map[String, String],
 619	) -> String {
 620	  let (message, omitted) = match error {
 621	    AdapterError(detail) => (detail, false)
 622	    InvalidConfig(detail) => (detail, false)
 623	    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
 624	    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
 625	    @json.InvalidNumber(position, _) =>
 626	      (
 627	        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
 628	        true,
 629	      )
 630	    _ => (error.to_string(), false)
 631	  }
 632	  diagnostic_text(message, environment?, omitted~)
 633	}
