 755	///|
 756	priv struct DiagnosticProtectedValues {
 757	  values : Array[String]
 758	  secrets : Array[String]
 759	  mut visited : Int32
 760	  mut incomplete : Bool
 761	}
 762	
 763	///|
 764	fn diagnostic_add_protected(
 765	  value : String,
 766	  output : String,
 767	  uncertain : Bool,
 768	  destination : Array[String],
 769	  result : DiagnosticProtectedValues,
 770	) -> Unit {
 771	  if value == "" ||
 772	    (
 773	      !output.contains(value) &&
 774	      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
 775	    ) {
 776	    return
 777	  }
 778	  if result.values.length() + result.secrets.length() >= 512 {
 779	    result.incomplete = true
 780	    return
 781	  }
 782	  destination.push(value)
 783	}
 784	
 785	///|
 786	fn diagnostic_protected_values(
 787	  value : Json,
 788	  result : DiagnosticProtectedValues,
 789	  output : String,
 790	  uncertain : Bool,
 791	  secret~ : Bool = false,
 792	  depth~ : Int32 = 0,
 793	) -> Unit {
 794	  if result.visited >= 65536 || depth >= 64 {
 795	    result.incomplete = true
 796	    return
 797	  }
 798	  result.visited += 1
 799	  match value {
 800	    Json::String(text) if text != "" => {
 801	      let destination = if secret { result.secrets } else { result.values }
 802	      diagnostic_add_protected(text, output, uncertain, destination, result)
 803	      for line in text.split("\n") {
 804	        if line != "" && line.length() < text.length() {
 805	          diagnostic_add_protected(
 806	            line.to_owned(),
 807	            output,
 808	            uncertain,
 809	            destination,
 810	            result,
 811	          )
 812	        }
 813	        for word in line.split(" ") {
 814	          for part in word.split("=") {
 815	            if part != "" && part.length() < text.length() {
 816	              diagnostic_add_protected(
 817	                part.to_owned(),
 818	                output,
 819	                uncertain,
 820	                destination,
 821	                result,
 822	              )
 823	            }
 824	          }
 825	        }
 826	      }
 827	      let escaped = Json::string(text).stringify()
 828	      if escaped.length() > 2 {
 829	        let encoded = escaped[1:escaped.length() - 1].to_owned()
 830	        if encoded != text {
 831	          diagnostic_add_protected(
 832	            encoded, output, uncertain, destination, result,
 833	          )
 834	        }
 835	      }
 836	    }
 837	    Json::Array(values) =>
 838	      for item in values {
 839	        diagnostic_protected_values(
 840	          item,
 841	          result,
 842	          output,
 843	          uncertain,
 844	          secret~,
 845	          depth=depth + 1,
 846	        )
 847	      }
 848	    Json::Object(values) =>
 849	      for name, item in values {
 850	        let key = name.to_lower().replace_all(old="_", new="")
 851	        diagnostic_protected_values(
 852	          item,
 853	          result,
 854	          output,
 855	          uncertain,
 856	          secret=secret || credential_field(name) || key == "pairingcode",
 857	          depth=depth + 1,
 858	        )
 859	      }
 860	    _ => ()
 861	  }
 862	}
