 864	///|
 865	fn diagnostic_output(
 866	  output : Bytes,
 867	  environment : Map[String, String],
 868	  protected_input? : String,
 869	  omitted~ : Bool = false,
 870	) -> String? {
 871	  if output.length() == 0 {
 872	    return None
 873	  }
 874	  let limit = if output.length() > 8192 { 8192 } else { output.length() }
 875	  let incomplete = omitted || limit < output.length()
 876	  let text = @utf8.decode_lossy(output[:limit])
 877	  let safeguards : DiagnosticProtectedValues = {
 878	    values: [],
 879	    secrets: [],
 880	    visited: 0,
 881	    incomplete: false,
 882	  }
 883	  if protected_input is Some(input) {
 884	    diagnostic_protected_values(
 885	      @json.parse(input),
 886	      safeguards,
 887	      text,
 888	      incomplete,
 889	    ) catch {
 890	      _ => safeguards.incomplete = true
 891	    }
 892	  }
 893	  if safeguards.incomplete {
 894	    return Some(
 895	      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
 896	    )
 897	  }
 898	  Some(
 899	    diagnostic_text(
 900	      text,
 901	      environment~,
 902	      omitted=incomplete,
 903	      protected_values=safeguards.values,
 904	      protected_secrets=safeguards.secrets,
 905	      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
 906	    ),
 907	  )
 908	}
