 918	///|
 919	fn DiagnosticCapture::new(limit : Int32) -> DiagnosticCapture {
 920	  {
 921	    output: @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 }),
 922	    limit,
 923	    truncated: false,
 924	    finished: false,
 925	  }
 926	}
