 928	///|
 929	async fn DiagnosticCapture::read(
 930	  self : DiagnosticCapture,
 931	  reader : @process.ReadFromProcess,
 932	) -> Unit {
 933	  try {
 934	    while reader.read_some(max_len=4096) is Some(chunk) {
 935	      let remaining = self.limit - self.output.length()
 936	      let count = if chunk.length() < remaining {
 937	        chunk.length()
 938	      } else {
 939	        remaining
 940	      }
 941	      if count > 0 {
 942	        self.output.write_bytes(chunk[:count])
 943	      }
 944	      if count < chunk.length() {
 945	        self.truncated = true
 946	      }
 947	    }
 948	  } catch {
 949	    error =>
 950	      if @async.is_being_cancelled() {
 951	        raise error
 952	      } else {
 953	        self.truncated = true
 954	      }
 955	  }
 956	  self.finished = true
 957	}
