 960	async fn wait_diagnostic_captures(captures : Array[DiagnosticCapture]) -> Unit {
 961	  @async.with_timeout(250, async fn() {
 962	    while captures.iter().any(capture => !capture.finished) {
 963	      @async.sleep(5)
 964	    }
 965	  }) catch {
 966	    error => if @async.is_being_cancelled() { raise error }
 967	  }
 968	}
