 970	///|
 971	async fn diagnostic_process_output(
 972	  program : String,
 973	  args : Array[String],
 974	  environment~ : Map[String, String],
 975	  cwd? : StringView,
 976	  stdin? : &@process.ProcessInput,
 977	  stdout_limit~ : Int32,
 978	  stderr_limit~ : Int32,
 979	) -> (Int32, Bytes, Bool, Bytes, Bool) {
 980	  let (out, stdout) = @process.read_from_process()
 981	  defer out.close()
 982	  let (err, stderr) = @process.read_from_process()
 983	  defer err.close()
 984	  @async.with_task_group(async fn(group) {
 985	    let child = @process.spawn(
 986	      group,
 987	      program,
 988	      args,
 989	      extra_env=environment,
 990	      inherit_env=false,
 991	      cwd?,
 992	      stdin?,
 993	      stdout~,
 994	      stderr~,
 995	    )
 996	    let output = DiagnosticCapture::new(stdout_limit)
 997	    let errors = DiagnosticCapture::new(stderr_limit)
 998	    group.spawn_bg(no_wait=true, async fn() { output.read(out) })
 999	    group.spawn_bg(no_wait=true, async fn() { errors.read(err) })
1000	    let status = child.wait()
1001	    while !output.finished {
1002	      @async.sleep(5)
1003	    }
1004	    wait_diagnostic_captures([errors])
1005	    (
1006	      status,
1007	      output.output.to_bytes(),
1008	      output.truncated,
1009	      errors.output.to_bytes(),
1010	      errors.truncated || !errors.finished,
1011	    )
1012	  })
1013	}
