307	///|
308	async fn Progress::message(
309	  self : Progress,
310	  text : String,
311	  debug~ : Bool,
312	  warning~ : Bool,
313	  emit~ : Bool = true,
314	) -> Unit {
315	  for line in text.split("\n") {
316	    let text = line.trim().to_owned()
317	    if text == "" {
318	      continue
319	    }
320	    guard self.safe_message(text) is Some(safe) else {
321	      self.details_truncated = true
322	      continue
323	    }
324	    if !debug || warning {
325	      self.remember(safe, warning~)
326	    }
327	    if !emit {
328	      continue
329	    }
330	    if safe.has_prefix("#") {
331	      guard safe.split_once(" ") is Some((id, rest)) &&
332	        id.length() > 1 &&
333	        id[1:].iter().all(c => c >= '0' && c <= '9') else {
334	        continue
335	      }
336	      let detail = rest.trim().to_owned()
337	      guard detail.has_prefix("[") ||
338	        detail.has_prefix("DONE") ||
339	        detail.has_prefix("ERROR") ||
340	        detail.has_prefix("CACHED") else {
341	        continue
342	      }
343	      if detail.has_prefix("ERROR") && debug && !warning {
344	        self.remember(safe, warning=true)
345	      }
346	      if self.builds.get(id.to_owned()) == Some(detail) {
347	        continue
348	      }
349	      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
350	        self.builds.set(id.to_owned(), detail)
351	      }
352	      progress_message("Build " + id.to_owned() + ": " + detail)
353	    } else if classic_build_step(safe) {
354	      // Classic RUN output has no prefix. Only its own completion marker
355	      // ends this mode; phase events on another pipe can arrive ahead of it.
356	      self.classic_build = true
357	      progress_message("Build " + safe)
358	    } else if safe.has_prefix("Successfully built ") ||
359	      safe.has_prefix("Successfully tagged ") {
360	      self.classic_build = false
361	      progress_message("Build: " + safe)
362	    } else if self.classic_build && !warning {
363	      continue
364	    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
365	      progress_message(self.stage + ": " + safe)
366	    } else if !debug && safe.has_prefix("[credential") {
367	      progress_message(self.stage + ": " + safe)
368	    }
369	  }
370	}

