 65	pub async fn ssh_proxy(args : Array[String], lease~ : String = "") -> Int32 {
 66	  guard args.length() > 0 else { raise AdapterError("Missing SSH transport") }
 67	  let pid = proxy_pid()
 68	  let start = process_start(pid)
 69	  let parent = proxy_parent()
 70	  let parent_start = process_start(parent)
 71	  guard parent > 1 && start > 0 && parent_start > 0 else {
 72	    raise AdapterError("SSH transport owner is unavailable")
 73	  }
 74	  ensure_supervisor()
 75	  let base = adapter_state_home() + "/transports"
 76	  @fs.mkdir(base, recursive=true, permission=0o700, allow_exist=true)
 77	  let directory = base + "/" + pid.to_string() + "." + start.to_string()
 78	  @fs.mkdir(directory, permission=0o700)
 79	  errdefer (if !@fs.exists(directory + "/state.json") {
 80	    @fs.rmdir(directory, recursive=true)
 81	  })
 82	  let lock = if lease == "" {
 83	    None
 84	  } else {
 85	    Some(
 86	      @fs.open(
 87	        lease,
 88	        mode=ReadWrite,
 89	        create_mode=OpenOrCreate,
 90	        permission=0o600,
 91	      ),
 92	    )
 93	  }
 94	  defer (if lock is Some(file) { file.close() })
 95	  if lock is Some(file) {
 96	    guard file.try_lock(Shared) else {
 97	      raise AdapterError("SSH proxy is closing")
 98	    }
 99	  }
100	  let state : Json = {
101	    "pid": pid.to_string(),
102	    "start": start.to_string(),
103	    "ownerPid": parent.to_string(),
104	    "ownerStart": parent_start.to_string(),
105	    "recording": @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
106	    "lease": if lease == "" {
107	      ""
108	    } else {
109	      @fs.realpath(lease)
110	    },
111	  }
112	  publish_file(directory + "/state.json", state.stringify())
113	  ensure_supervisor()
