197	///|
198	async fn read_codex_auth(home : String) -> CodexAuth {
199	  guard @fs.file_size(home + "/auth.json") <= 65536L else {
200	    raise AdapterError("Invalid Codex auth size")
201	  }
202	  let source = @fs.read_file(home + "/auth.json")
203	  guard source.binary().length() <= 65536 else {
204	    raise AdapterError("Invalid Codex auth size")
205	  }
206	  let auth = @json.parse(source.text())
207	  guard (
208	      field(auth, "OPENAI_API_KEY") == None ||
209	      field(auth, "OPENAI_API_KEY") == Some(Json::null())
210	    ) &&
211	    (
212	      field(auth, "auth_mode") == None ||
213	      field(auth, "auth_mode") == Some(Json::string("chatgpt"))
214	    ) else {
215	    raise AdapterError("Unsupported Codex auth mode")
216	  }
217	  guard field(auth, "tokens") is Some(tokens) else {
218	    raise AdapterError("Missing Codex auth tokens")
219	  }
220	  let access = required(tokens, "access_token")
221	  let secrets = [access]
222	  for name in ["id_token", "refresh_token"] {
223	    if field(tokens, name) is Some(Json::String(value)) && value != "" {
224	      secrets.push(value)
225	    }
226	  }
227	  let segments = access.split(".").to_array()
228	  guard segments.length() == 3 else {
229	    raise AdapterError("Invalid access token")
230	  }
231	  let encoded = segments[1]
232	    .to_owned()
233	    .replace_all(old="-", new="+")
234	    .replace_all(old="_", new="/")
235	  let padding = (4 - encoded.length() % 4) % 4
236	  let claims = @json.parse(
237	    @utf8.decode(@base64.decode(encoded + "=".repeat(padding))),
238	  )
239	  guard field(claims, "exp") is Some(Json::Number(expiry, ..)) else {
240	    raise AdapterError("Invalid access token expiry")
241	  }
242	  { access, account: required(tokens, "account_id"), expiry, secrets, }
243	}
244	
245	///|
246	async fn codex_rpc_response(
247	  reader : @process.ReadFromProcess,
248	  id : Int32,
249	  secrets : Array[String],
250	) -> Unit {
251	  let bytes : Array[Byte] = []
252	  let mut total = 0
253	  while true {
254	    let byte = reader.read_exactly(1)[0]
255	    total += 1
256	    guard total <= 1048576 else {
257	      raise AdapterError("Codex refresh output limit")
258	    }
259	    if byte == b'\n' {
260	      let response = @json.parse(@utf8.decode(Bytes::from_array(bytes)))
261	      bytes.clear()
262	      if field(response, "id") == Some(Json::number(id.to_double())) {
263	        if field(response, "error") is Some(error) {
264	          let code = match field(error, "code") {
265	            Some(Json::Number(value, ..)) => " code " + value.to_string()
266	            _ => ""
267	          }
268	          let message = match field(error, "message") {
269	            Some(Json::String(value)) =>
270	              ": " + diagnostic_text(value, protected_secrets=secrets)
271	            _ => ""
272	          }
273	          raise AdapterError("Codex refresh RPC \{id} failed" + code + message)
274	        }
275	        guard field(response, "result") != None else {
276	          raise AdapterError("Codex refresh RPC \{id} returned no result")
277	        }
278	        return
279	      }
280	    } else {
281	      bytes.push(byte)
282	    }
283	  }
284	}
