   232	      "/orca-env-devsy/events.jsonl"
   233	    for line in @fs.read_file(path).text().split("\n") {
   234	      if line == "" {
   235	        continue
   236	      }
   237	      let event = @json.parse(line.to_owned())
   238	      if field(event, "status") != Some(Json::string("process-error")) {
   239	        continue
   240	      }
   241	      let safe = Json::empty_object()
   242	      for name in ["process_os", "process_utf8", "process_api"] {
   243	        if field(event, "errorType") == Some(Json::string(name)) {
   244	          set_field(safe, "errorType", Json::string(name))
   245	        }
   246	      }
   247	      for name in ["read"] {
   248	        if field(event, "phase") == Some(Json::string(name)) {
   249	          set_field(safe, "phase", Json::string(name))
   250	        }
   251	      }
   252	      if field(event, "osErrno") is Some(Json::Number(code, ..)) &&
   253	        code > 0 &&
   254	        code < 4096 &&
   255	        code == code.to_int().to_double() {
   256	        set_field(safe, "osErrno", Json::number(code))
   257	      }
   258	      diagnostics.push(safe.stringify())
   259	    }
   260	  } catch {
   261	    _ => ()
   262	  }
